for a from 1 to py_int(SIDES + 1) {
    for b from 1 to py_int(SIDES + 1) {
        sums[(py_int(a + b)) + 0.0] = (py_int(get(sums, py_int(a + b), 0) + 1)) + 0.0
    }
}
print(fmt(sums, "d", "d"))
# @@ a bar per key, in key order
py_s1 = py_sort(keys(sums))
for py_i2 to len(py_s1) {
    total = py_s1[py_i2]
    print(fmt(total + 0.0, "2d"), ("#" * py_mget(sums, total)))
}
# @@ the most likely sum
